UPDATE public.corretor_studio_leads l
SET age = ba.new_age
FROM backup_ages ba
WHERE l.id = ba.lead_id::uuid
  AND l.age IS DISTINCT FROM ba.new_age;

-- Part 2: convert remaining range-format leads (those not covered by backup)
UPDATE public.corretor_studio_leads
SET age = (
  SELECT string_agg(new_age || ':' || cnt, ',' ORDER BY new_age::int)
  FROM (
    SELECT
      CASE split_part(part, ':', 1)
        WHEN '00_18'   THEN '9'
        WHEN '19_23'   THEN '21'
        WHEN '24_28'   THEN '26'
        WHEN '29_33'   THEN '31'
        WHEN '34_38'   THEN '36'
        WHEN '39_43'   THEN '41'
        WHEN '44_48'   THEN '46'
        WHEN '49_53'   THEN '51'
        WHEN '54_58'   THEN '56'
        WHEN '59_plus' THEN '62'
        ELSE NULL
      END AS new_age,
      split_part(part, ':', 2) AS cnt
    FROM regexp_split_to_table(age, ',') AS part
    WHERE part ~ '_'
  ) sub
  WHERE new_age IS NOT NULL
)
WHERE age ~ '_';
